<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { request, query, session, can, type Page } from '../api'
import { centsFromInput, money } from '../domain.js'
import Modal from './Modal.vue'
const rows=ref<any[]>([]),page=ref(1),total=ref(0),search=ref(''),tagFilter=ref(''),loading=ref(false),busy=ref(false),error=ref(''),editing=ref<any>(null),form=ref<Record<string,any>>({})
const companies=ref<any[]>([]),company=ref(''),month=ref(new Date().getFullYear()+'-'+String(new Date().getMonth()+1).padStart(2,'0'))
const companyError=ref(''),companySuccess=ref(''),companyLoading=ref(false),tags=ref<any[]>([]),target=ref<any>(null),targetAmount=ref('')
let companyRead=0
const tagEditing=ref<any>(null),tagForm=ref({name:'',color:'#64748b',status:'active'})
const tagging=ref<any>(null),tagOptions=ref<any[]>([]),selectedTags=ref<number[]>([])
const platform=computed(()=>session.role==='platform')
const companyOrg=computed(()=>platform.value?Number(company.value):Number(session.user?.org_id))
const stages:Record<string,string>={new:'新客户',viewing:'看船中',contacted:'已联系',quoted:'已报价',won:'已成交',lost:'未成交',archived:'已归档'}
async function load(){loading.value=true;error.value='';try{const result=await request<Page>('/customers'+query({page:page.value,page_size:10,search:search.value,tag_id:tagFilter.value}));rows.value=result.items;total.value=result.total}catch(err){error.value=(err as Error).message}finally{loading.value=false}}
function edit(row?:any){editing.value=row||{};form.value={user_id:row?.user_id||'',broker_id:row?.broker_id||'',name:row?.name||'',stage:row?.stage||'new',notes:row?.notes||''};error.value=''}
async function save(){if(busy.value)return;busy.value=true;error.value='';try{const existing=!!editing.value.id;const body=existing?{stage:form.value.stage,notes:form.value.notes}:{user_id:Number(form.value.user_id),broker_id:Number(form.value.broker_id),name:form.value.name,notes:form.value.notes};if(!existing&&(!Number.isSafeInteger(body.user_id)||Number(body.user_id)<=0))throw new Error('请选择已注册客户的有效用户编号');await request('/customers'+(existing?'/'+editing.value.id:''),{method:existing?'PATCH':'POST',body:JSON.stringify(body)});editing.value=null;await load()}catch(err){error.value=(err as Error).message}finally{busy.value=false}}
async function loadCompany(){
  const version=++companyRead,orgId=companyOrg.value,selectedMonth=month.value
  companyError.value='';companySuccess.value='';tags.value=[];target.value=null;targetAmount.value=''
  companyLoading.value=false
  if(!Number.isSafeInteger(orgId)||orgId<=0)return
  companyLoading.value=true
  try{
    const [tagResult,targetResult]=await Promise.all([request<Page>('/customer-tags'+query({org_id:orgId})),request<any>('/agency-targets'+query({month:selectedMonth,org_id:orgId}))])
    if(version!==companyRead)return
    tags.value=tagResult.items;target.value=targetResult;targetAmount.value=targetResult.configured?(Number(targetResult.target_amount_cents)/100).toFixed(2):''
  }catch(err){if(version===companyRead)companyError.value=(err as Error).message}finally{if(version===companyRead)companyLoading.value=false}
}
async function saveTarget(){
  if(busy.value||!companyOrg.value)return;busy.value=true;companyError.value='';companySuccess.value=''
  try{target.value=await request('/agency-targets/'+month.value,{method:'PUT',body:JSON.stringify({target_amount_cents:centsFromInput(targetAmount.value),...(platform.value?{org_id:companyOrg.value}:{})})});companySuccess.value='月度目标已保存，实际进度以交易流水为准'}catch(err){companyError.value=(err as Error).message}finally{busy.value=false}
}
function editTag(tag?:any){tagEditing.value=tag||{};tagForm.value={name:tag?.name||'',color:tag?.color||'#64748b',status:tag?.status||'active'};companyError.value=''}
async function saveTag(){
  if(busy.value||!companyOrg.value)return;busy.value=true;companyError.value=''
  try{const existing=!!tagEditing.value.id;await request('/customer-tags'+(existing?'/'+tagEditing.value.id:''),{method:existing?'PATCH':'POST',body:JSON.stringify({...tagForm.value,...(!existing&&platform.value?{org_id:companyOrg.value}:{})})});tagEditing.value=null;await loadCompany();await load()}catch(err){companyError.value=(err as Error).message}finally{busy.value=false}
}
async function assignTags(row:any){
  error.value='';busy.value=true
  try{if(!Number.isSafeInteger(Number(row.org_id))||Number(row.org_id)<=0)throw new Error('该客户尚无经纪公司归属，不能读取公司标签');const result=await request<Page>('/customer-tags'+query({org_id:row.org_id}));tagOptions.value=result.items.filter(tag=>tag.status==='active');selectedTags.value=(row.tags||[]).filter((tag:any)=>tag.status==='active').map((tag:any)=>Number(tag.id));tagging.value=row}catch(err){error.value=(err as Error).message}finally{busy.value=false}
}
async function saveTags(){
  if(busy.value||!tagging.value)return;busy.value=true;error.value=''
  try{await request('/customers/'+tagging.value.id+'/tags',{method:'PUT',body:JSON.stringify({tag_ids:selectedTags.value})});tagging.value=null;await load()}catch(err){error.value=(err as Error).message}finally{busy.value=false}
}
onMounted(async()=>{await load();if(platform.value&&can('organizations'))try{const result=await request<Page>('/admin/organizations?page_size=500');companies.value=result.items.filter(item=>item.kind==='agency')}catch(err){companyError.value=(err as Error).message}if(!platform.value)await loadCompany()})
</script>
<template>
  <div class="page-heading"><div><h1>客户管理</h1><p>记录客户跟进阶段。各经纪公司及所属经纪人的客户数据由服务端隔离。</p></div><button class="button primary" @click="edit()">＋ 添加客户</button></div><p v-if="error&&!editing" class="notice danger" role="alert">{{ error }}</p>
  <section class="panel"><form class="filter-bar" @submit.prevent="page=1;load()"><label class="search-field"><span>⌕</span><input v-model="search" placeholder="搜索客户" aria-label="搜索客户" /></label><select v-model="tagFilter" aria-label="客户标签筛选"><option value="">全部客户标签</option><option v-for="tag in tags" :key="tag.id" :value="String(tag.id)">{{ tag.name }}{{ tag.status==='inactive'?'（停用）':'' }}</option></select><button class="button">查询</button><span class="record-count">共 {{ total }} 位客户</span></form><div class="table-scroll"><table><thead><tr><th>客户姓名</th><th>用户编号</th><th>经纪人</th><th>跟进阶段</th><th>标签</th><th>跟进备注</th><th>操作</th></tr></thead><tbody><tr v-if="loading"><td colspan="7" class="empty">正在加载…</td></tr><tr v-else-if="!rows.length"><td colspan="7" class="empty">暂无客户</td></tr><tr v-for="row in rows" v-else :key="row.id"><td class="cell-title">{{ row.name }}</td><td>#{{ row.user_id }}</td><td>#{{ row.broker_id||row.owner_id||'—' }}</td><td>{{ stages[row.stage]||row.stage||'新客户' }}</td><td><span v-for="tag in row.tags||[]" :key="tag.id" class="status-badge" :style="{color:tag.color}">{{ tag.name }}{{ tag.status==='inactive'?'（停用）':'' }}</span><span v-if="!row.tags?.length" class="muted">—</span></td><td class="cell-truncate">{{ row.notes||'—' }}</td><td><button class="text-button" @click="edit(row)">跟进 / 编辑</button><button class="text-button" :disabled="busy" @click="assignTags(row)">客户标签</button></td></tr></tbody></table></div><div class="pagination"><span>第 {{ page }} 页</span><button class="button small" :disabled="page<=1||loading" @click="page--;load()">上一页</button><button class="button small" :disabled="page*10>=total||loading" @click="page++;load()">下一页</button></div></section>
  <section class="panel"><div class="panel-heading"><h2>公司月度目标与标签</h2></div><p v-if="companyError&&!tagEditing" class="notice danger" role="alert">{{ companyError }}</p><p v-if="companySuccess" class="notice success" role="status">{{ companySuccess }}</p><form class="filter-bar" @submit.prevent="loadCompany"><label v-if="platform&&can('organizations')"><span>经纪公司</span><select v-model="company" :disabled="busy" aria-label="选择经纪公司" @change="loadCompany"><option value="">请选择公司</option><option v-for="item in companies" :key="item.id" :value="String(item.id)">{{ item.name }}</option></select></label><label v-else-if="platform"><span>经纪公司编号</span><input v-model="company" :disabled="busy" type="number" min="1" aria-label="经纪公司编号" @change="loadCompany" /><small>当前账号无机构列表权限，请使用获授权的公司编号。</small></label><label><span>目标月份</span><input v-model="month" :disabled="busy" type="month" required @change="loadCompany" /></label><button class="button" :disabled="companyLoading||!companyOrg">{{ companyLoading?'正在读取…':'刷新公司设置' }}</button></form><p v-if="!companyOrg" class="inline-empty">选择经纪公司后读取目标与标签。</p><template v-else><p v-if="!target&&!companyLoading&&!companyError" class="inline-empty">尚未取得公司目标。</p><template v-if="target"><p v-if="!target.configured" class="notice">本公司此月份尚未设置目标。</p><div class="order-summary"><div><span>目标净实收</span><strong>{{ target.configured?money(target.target_amount_cents):'尚未设置' }}</strong></div><div><span>当月实收 / 退款</span><strong>{{ money(target.actual_paid_cents) }} / {{ money(target.actual_refund_cents) }}</strong></div><div><span>当月净实收</span><strong>{{ money(target.actual_net_paid_cents) }}</strong></div></div><form class="filter-bar" @submit.prevent="saveTarget"><label><span>月度净实收目标（元） *</span><input v-model="targetAmount" :disabled="busy" inputmode="decimal" required /></label><button class="button primary" :disabled="busy||companyLoading">保存月度目标</button></form><p class="muted">按当月实际支付流水减当月退款流水统计，包括历史订单在本月的退款；报价和创建订单不计入业绩。</p></template><div class="panel-heading"><h3>公司客户标签</h3><button class="button small" :disabled="companyLoading||busy" @click="editTag()">＋ 新建标签</button></div><div class="table-scroll"><table><thead><tr><th>标签名称</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-if="!tags.length"><td colspan="3" class="empty">{{ companyLoading?'正在读取…':'暂无公司标签' }}</td></tr><tr v-for="tag in tags" :key="tag.id"><td :style="{color:tag.color}">{{ tag.name }}</td><td>{{ tag.status==='active'?'启用':'停用' }}</td><td><button class="text-button" @click="editTag(tag)">编辑标签</button></td></tr></tbody></table></div></template></section>
  <Modal v-if="editing" :title="editing.id?'更新客户跟进':'添加客户'" @close="!busy&&(editing=null)"><form id="customer-form" class="form-grid" @submit.prevent="save"><p v-if="error" class="notice danger span-all" role="alert">{{ error }}</p><label v-if="!editing.id"><span>已注册用户 ID *</span><input v-model="form.user_id" type="number" min="1" required /></label><label v-if="!editing.id"><span>负责销售经纪人 ID *</span><input v-model="form.broker_id" type="number" min="1" required /></label><label v-if="!editing.id"><span>客户名称 *</span><input v-model="form.name" required /></label><label v-if="editing.id" class="span-all"><span>跟进阶段</span><select v-model="form.stage"><option v-for="(label,key) in stages" :key="key" :value="key">{{ label }}</option></select></label><label class="span-all"><span>跟进备注</span><textarea v-model="form.notes" rows="5" /></label></form><template #footer><button class="button" :disabled="busy" @click="editing=null">取消</button><button form="customer-form" class="button primary" :disabled="busy">{{ busy?'正在保存…':'保存跟进' }}</button></template></Modal>
  <Modal v-if="tagEditing" :title="tagEditing.id?'编辑公司标签':'新建公司标签'" @close="!busy&&(tagEditing=null)"><form id="tag-form" class="form-grid" @submit.prevent="saveTag"><p v-if="companyError" class="notice danger span-all" role="alert">{{ companyError }}</p><label class="span-all"><span>标签名称 *</span><input v-model="tagForm.name" maxlength="80" required /></label><label><span>标签颜色</span><input v-model="tagForm.color" type="color" /></label><label><span>标签状态</span><select v-model="tagForm.status"><option value="active">启用</option><option value="inactive">停用</option></select></label></form><template #footer><button class="button" :disabled="busy" @click="tagEditing=null">取消</button><button class="button primary" form="tag-form" :disabled="busy">保存标签</button></template></Modal>
  <Modal v-if="tagging" :title="`客户标签 · ${tagging.name}`" @close="!busy&&(tagging=null)"><form id="customer-tags-form" @submit.prevent="saveTags"><p v-if="error" class="notice danger" role="alert">{{ error }}</p><p class="muted">仅选择客户所属公司的启用标签。保存将替换当前标记，取消选择可移除。</p><p v-if="tagging.tags?.some((tag:any)=>tag.status==='inactive')" class="notice">本次保存会移除已停用标签。</p><p v-if="!tagOptions.length" class="inline-empty">该公司暂无启用标签，可由公司管理员创建。</p><label v-for="tag in tagOptions" :key="tag.id" class="recipient-row"><input v-model="selectedTags" type="checkbox" :value="Number(tag.id)" /><span :style="{color:tag.color}">{{ tag.name }}</span></label></form><template #footer><button class="button" :disabled="busy" @click="tagging=null">取消</button><button class="button primary" form="customer-tags-form" :disabled="busy">保存客户标签</button></template></Modal>
</template>
